INSERT INTO `v1_3c4dfe98aa2a6079d807a394ff2ce5fe25d112047433ff7c59b182303f0fb2ac` VALUES (1, 3001, 0.0, "2030/01/01 14:59:59", 2, 130011, 3001100, 2.1, "ミッションねえ……\nちょうどいいや\nどこまで片付けられるか\n賭けをしようじゃないか", "2024/10/31 12:00:00", "ヤマト", 100, -416.5);
INSERT INTO `v1_3c4dfe98aa2a6079d807a394ff2ce5fe25d112047433ff7c59b182303f0fb2ac` VALUES (4, 3001, 0.0, "2030/01/01 14:59:59", 2, 130011, 3001101, 5.68, "他人から言われた任務を\n言われるままにやるなんざ\n性に合わないんだがね……\nま、報酬は貰っとこうか", "2024/10/31 12:00:00", "ヤマト", 101, -416.5);
INSERT INTO `v1_3c4dfe98aa2a6079d807a394ff2ce5fe25d112047433ff7c59b182303f0fb2ac` VALUES (1, 3001, 0.0, "2030/01/01 14:59:59", 1, 130011, 3001102, 0.0, "なんだい？　やれンなら\nとっとと済ませちまいな。\nフブキが早くやることやれ\nってボヤいてたよ。", "2024/10/31 12:00:00", "ヤマト", 102, -416.5);
INSERT INTO `v1_3c4dfe98aa2a6079d807a394ff2ce5fe25d112047433ff7c59b182303f0fb2ac` VALUES (1, 3002, 0.0, "2030/01/01 14:59:59", 1, 130211, 3002100, 0.0, "え～？　ぼくに頼みごと～？\nどうしちゃおっかな～\nちゃんとお願いできたら\n考えてあげよっかな～？", "2024/10/31 12:00:00", "フブキ", 100, -416.5);
INSERT INTO `v1_3c4dfe98aa2a6079d807a394ff2ce5fe25d112047433ff7c59b182303f0fb2ac` VALUES (1, 3002, 0.0, "2030/01/01 14:59:59", 1, 130211, 3002101, 0.0, "ほらほらぁ、これが\n欲しいんでしょ～？\nほんと、しょうがないよね～\nザコおに～いさん♡", "2024/10/31 12:00:00", "フブキ", 101, -416.5);
INSERT INTO `v1_3c4dfe98aa2a6079d807a394ff2ce5fe25d112047433ff7c59b182303f0fb2ac` VALUES (5, 3002, 0.0, "2030/01/01 14:59:59", 2, 130211, 3002102, 8.53, "へえ～、欲しいんだ～？\nぼくのた・い・せ・つ・な・モ・ノ\nあははっ！　なに考えてんの？\nもうへんふしじゃ～んｗ", "2024/10/31 12:00:00", "フブキ", 102, -416.5);
INSERT INTO `v1_3c4dfe98aa2a6079d807a394ff2ce5fe25d112047433ff7c59b182303f0fb2ac` VALUES (7, 3002, 0.0, "2030/01/01 14:59:59", 1, 130211, 3002103, 5.67, "なになに～？　もしかしてまた\nおねだりするつもりなんだ？\nとか言って、ほんとはぼくに\n会いたいだけだったりして～？", "2024/10/31 12:00:00", "フブキ", 103, -416.5);
INSERT INTO `v1_3c4dfe98aa2a6079d807a394ff2ce5fe25d112047433ff7c59b182303f0fb2ac` VALUES (1, 3002, 0.0, "2030/01/01 14:59:59", 1, 130211, 3002104, 0.0, "ザコお兄さんってぇ\n頼み方もワンパなのぉ～？\nもっと必死にならないと\nぼくの心は動かせないよ～？", "2024/10/31 12:00:00", "フブキ", 104, -416.5);
INSERT INTO `v1_3c4dfe98aa2a6079d807a394ff2ce5fe25d112047433ff7c59b182303f0fb2ac` VALUES (3, 3004, 0.0, "2030/01/01 14:59:59", 3, 130211, 3002300, 0.0, "あのさーザコお兄さん、\nな～んか調子乗ってない？\nぼくのこと、なんでもくれる\nチョロいやつとか思ってたりー？", "2024/10/31 12:00:00", "フブキ", 300, -416.5);
INSERT INTO `v1_3c4dfe98aa2a6079d807a394ff2ce5fe25d112047433ff7c59b182303f0fb2ac` VALUES (7, 3005, 0.0, "2030/01/01 14:59:59", 7, 130211, 3002400, 0.0, "ざんね～ん♪\nうざいお兄さんには、もうな～んにもあげませ～ん♡\nほんとなっさけなーい♪\nばいば～い♡", "2024/10/31 12:00:00", "フブキ", 301, -416.5);
INSERT INTO `v1_3c4dfe98aa2a6079d807a394ff2ce5fe25d112047433ff7c59b182303f0fb2ac` VALUES (2, 3003, 0.0, "2030/01/01 14:59:59", 1, 130211, 3003200, 4.4, "きゃはは、ほんと必死～♡\nは～、面白かった。\n笑えたからいいよ～\nそれ、恵んだげる～♪", "2024/10/31 12:00:00", "フブキ", 200, -416.5);
INSERT INTO `v1_3c4dfe98aa2a6079d807a394ff2ce5fe25d112047433ff7c59b182303f0fb2ac` VALUES (7, 3003, 0.0, "2030/01/01 14:59:59", 7, 130211, 3003201, 0.0, "は～、しょうがないな～♡\nザコお兄さんってば\nほんとよわよわで\n情けないよね～ｗ", "2024/10/31 12:00:00", "フブキ", 201, -416.5);
INSERT INTO `v1_3c4dfe98aa2a6079d807a394ff2ce5fe25d112047433ff7c59b182303f0fb2ac` VALUES (1, 3003, 0.0, "2030/01/01 14:59:59", 2, 130211, 3003202, 5.6, "お兄さんってば、ぼくがいないと\nほんとザッコザコだよね～\nもっと感謝しろし～♪", "2024/10/31 12:00:00", "フブキ", 202, -416.5);
